def obter_chave_casulo(rua_nome, lado, coluna, nivel):
    try:
        col_int = int(coluna)
    except:
        col_int = 1
    return f"{rua_nome}|{lado}|{col_int:03d}|{str(nivel).upper()}"

def obter_chave_estoque(categoria_peca, estacao):
    return f"{categoria_peca}|{estacao}"

def obter_lados_colunas_rua(r_nome, r_cfg):
    """Retorna lista de (lado, colunas) cobrindo TODAS as posições da rua,
    incluindo colunas especiais como madeira e metal isolados (ex: Rua 15).
    Sem isso, posições que ficam só em 'madeira' ou 'metal' nunca entram
    no base_dados_cd e somem do Visualizador."""
    if "cols_seq" in r_cfg:
        return [("seq", r_cfg["cols_seq"])]
    lados = [
        ("impar", r_cfg.get("cols_impar", [])),
        ("par",   r_cfg.get("cols_par",   [])),
    ]
    # Colunas especiais que não estão em cols_impar nem cols_par
    todas_normais = set(r_cfg.get("cols_impar", [])) | set(r_cfg.get("cols_par", []))
    extras_impar = [c for c in r_cfg.get("madeira", []) + r_cfg.get("metal", [])
                    if c not in todas_normais and c % 2 == 1]
    extras_par   = [c for c in r_cfg.get("madeira", []) + r_cfg.get("metal", [])
                    if c not in todas_normais and c % 2 == 0]
    if extras_impar:
        lados.append(("impar", sorted(extras_impar)))
    if extras_par:
        lados.append(("par", sorted(extras_par)))
    return lados

def obter_especificacao_casulo(rua_nome, coluna, lado="impar"):
    """
    Retorna a especificação física de uma coluna/lado de uma rua: níveis
    válidos, tipo estrutural (aramado_P/aramado_M/aramado_G/madeira/
    metal_profundo/metal_raso) e descrição.
    """
    try:
        col = int(coluna)
    except (ValueError, TypeError):
        col = 1

    config = ESTRUTURA_CD.get(rua_nome, {})
    tipo = config.get("tipo", "")
    vazio = {"niveis": [], "tipo_estrutural": None, "tipo_desc": "Inexistente"}

    if tipo in ("Inexistente", "Morta"):
        return vazio

    # Metal tem prioridade sobre qualquer tipo estrutural
    if "metal" in config and col in config["metal"]:
        return {"niveis": NIVEIS_METAL_5, "tipo_estrutural": "metal_raso", "tipo_desc": "Metal"}
    if "metal_cols" in config and col in config["metal_cols"]:
        return {"niveis": NIVEIS_METAL_5, "tipo_estrutural": "metal_raso", "tipo_desc": "Metal"}

    # Madeira (Rua 15: cols 89, 91)
    if "madeira" in config and col in config["madeira"]:
        return {"niveis": ["D", "G", "J", "M", "P"], "tipo_estrutural": "madeira", "tipo_desc": "Madeira"}

    if tipo in ("Aramado_P_Seq_20", "P"):
        return {"niveis": NIVEIS_P, "tipo_estrutural": "aramado_P", "tipo_desc": "Pequeno (P)"}

    elif tipo == "G":
        # Rua 16: lado ÍMPAR é G o tempo todo (45-139).
        # Só o lado PAR vira M a partir da col 102.
        if rua_nome == "Rua 16" and lado == "par" and col >= 102:
            return {"niveis": NIVEIS_M, "tipo_estrutural": "aramado_M", "tipo_desc": "Médio (M)"}
        return {"niveis": NIVEIS_G, "tipo_estrutural": "aramado_G", "tipo_desc": "Grande (G)"}

    elif tipo == "M":
        return {"niveis": NIVEIS_M, "tipo_estrutural": "aramado_M", "tipo_desc": "Médio (M)"}

    elif tipo == "G_Unilateral":
        if lado == "par":
            return {"niveis": NIVEIS_G, "tipo_estrutural": "aramado_G", "tipo_desc": "Grande (G) — Unilateral"}
        return vazio

    elif tipo == "Metal_Seq_21":
        return {"niveis": NIVEIS_METAL_5, "tipo_estrutural": "metal_raso", "tipo_desc": "Metal Sequencial"}

    elif tipo == "Especial_Rua_14":
        if 1 <= col <= 23:
            return {"niveis": ["D", "G", "J", "M", "P"], "tipo_estrutural": "madeira", "tipo_desc": "Rua 14 — Madeira Gigante"}
        elif col in range(26, 33):
            return {"niveis": NIVEIS_METAL_5, "tipo_estrutural": "metal_profundo", "tipo_desc": "Rua 14 — Metal Profundo"}
        elif col in range(42, 49):
            return {"niveis": NIVEIS_METAL_5, "tipo_estrutural": "metal_raso", "tipo_desc": "Rua 14 — Metal Raso"}
        return vazio

    elif tipo == "Misto_Transicao_R02":
        # Ímpar 21-93 e par 22-102 → P; seq 103-139 → G
        if col >= 103:
            return {"niveis": NIVEIS_G, "tipo_estrutural": "aramado_G", "tipo_desc": "Grande (G)"}
        return {"niveis": NIVEIS_P, "tipo_estrutural": "aramado_P", "tipo_desc": "Pequeno (P)"}

    elif tipo == "Misto_Transicao":
        # Compatibilidade com dados antigos no Supabase
        if col < 103:
            return {"niveis": NIVEIS_P, "tipo_estrutural": "aramado_P", "tipo_desc": "Pequeno (P)"}
        return {"niveis": NIVEIS_G, "tipo_estrutural": "aramado_G", "tipo_desc": "Grande (G)"}

    elif tipo == "Misto_Lado":
        if lado == "par":
            return {"niveis": NIVEIS_G, "tipo_estrutural": "aramado_G", "tipo_desc": "Grande (G)"}
        return {"niveis": NIVEIS_P, "tipo_estrutural": "aramado_P", "tipo_desc": "Pequeno (P)"}

    elif tipo == "Misto_Lado_15":
        # Par → M | Ímpar 1-87 → M | 89,91 madeira e 93 metal já tratados acima
        return {"niveis": NIVEIS_M, "tipo_estrutural": "aramado_M", "tipo_desc": "Médio (M)"}

    return {"niveis": NIVEIS_P, "tipo_estrutural": "aramado_P", "tipo_desc": "Padrão"}

def obter_faixa_categoria(categoria_peca, tipo_estrutural, estacao, rua_nome):
    """Faixa (mín,máx) pura da tabela por categoria — usada só para checar a
    regra de PERMISSÃO (ex: Jaquetas Pesadas = None = proibido em P/M/G),
    independente de haver densidade fixa por rua."""
    genero = obter_genero_rua(rua_nome)
    tabela_verao, tabela_inverno = obter_tabelas_genero(genero)
    tabela = tabela_inverno if estacao == "Inverno" else tabela_verao
    categoria_casulo = CATEGORIA_CASULO_POR_TIPO_ESTRUTURAL.get(tipo_estrutural, "P")
    return tabela.get(categoria_peca, {}).get(categoria_casulo)

def peca_permitida(categoria_peca, tipo_estrutural, estacao, rua_nome):
    return obter_faixa_categoria(categoria_peca, tipo_estrutural, estacao, rua_nome) is not None

def obter_faixa_capacidade(categoria_peca, tipo_estrutural, estacao, rua_nome):
    """Faixa exibida na tela: densidade fixa da rua quando existir, senão a
    faixa da tabela por categoria."""
    fixa = CAPACIDADE_FIXA_POR_RUA.get(rua_nome, {}).get(tipo_estrutural)
    if fixa is not None:
        return (fixa, fixa)
    return obter_faixa_categoria(categoria_peca, tipo_estrutural, estacao, rua_nome)

def obter_capacidade_minima(categoria_peca, tipo_estrutural, estacao, rua_nome):
    # A proibição (ex: Jaquetas Pesadas em aramado) vale sempre, mesmo em
    # ruas com densidade fixa.
    if not peca_permitida(categoria_peca, tipo_estrutural, estacao, rua_nome):
        return 0

    fixa = CAPACIDADE_FIXA_POR_RUA.get(rua_nome, {}).get(tipo_estrutural)
    if fixa is not None:
        return fixa

    faixa = obter_faixa_categoria(categoria_peca, tipo_estrutural, estacao, rua_nome)
    valor = faixa[0] if faixa else 0
    if valor and tipo_estrutural == "aramado_P":
        valor = min(valor, TRAVA_MAXIMA_P)
    if valor and tipo_estrutural == "aramado_M" and "Vestido" in categoria_peca:
        valor = min(valor, TRAVA_MAXIMA_M_VESTIDOS)
    return valor

def obter_capacidade_estimada_exibicao(tipo_estrutural, rua_nome):
    fixa = CAPACIDADE_FIXA_POR_RUA.get(rua_nome, {}).get(tipo_estrutural)
    if fixa is not None:
        return fixa
    return obter_capacidade_minima(CATEGORIA_REFERENCIA_DISPLAY, tipo_estrutural, "Verão", rua_nome)

def calcular_pecas_totais(dados_casulo):
    return sum(dados_casulo.values()) if dados_casulo else 0

def botao_exportar_excel(df, nome_arquivo, label="📥 Baixar em Excel (.xlsx)", key=None):
    """Gera um .xlsx de verdade (células reais) em vez de depender do CSV
    embutido do st.dataframe, que quebra no Excel em pt-BR (separador ; vs ,)."""
    if df is None or df.empty:
        return
    if not OPENPYXL_DISPONIVEL:
        st.caption("⚠️ Exportação em Excel indisponível neste ambiente (adicione `openpyxl` ao requirements.txt do repositório).")
        return
    buffer_excel = BytesIO()
    with pd.ExcelWriter(buffer_excel, engine="openpyxl") as writer:
        df.to_excel(writer, index=False, sheet_name="Dados")
    st.download_button(
        label=label,
        data=buffer_excel.getvalue(),
        file_name=nome_arquivo,
        mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        key=key,
    )

def calcular_fracao_ocupada(dados_casulo, tipo_estrutural, rua_nome):
    """
    % de ocupação real do casulo, considerando o mix de categorias/estações
    guardado nele. Cada combinação consome capacidade proporcional ao seu
    próprio mínimo de faixa (fração = qtd / capacidade_mínima daquela peça).
    """
    if not dados_casulo:
        return 0.0
    fracao = 0.0
    for chave_combo, qtd in dados_casulo.items():
        categoria_peca, estacao = chave_combo.split("|", 1)
        cap_min = obter_capacidade_minima(categoria_peca, tipo_estrutural, estacao, rua_nome)
        if cap_min > 0:
            fracao += qtd / cap_min
    return fracao

def obter_capacidade_estimada_segura(tipo_estrutural, rua_nome):
    """Igual obter_capacidade_estimada_exibicao, mas nunca deixa a
    capacidade virar 0/None — cai num valor genérico (20) quando a
    combinação de tipo/rua não tem nada cadastrado na tabela de capacidade.
    Usado pelas posições que só existem no dado real da ID Brasil e ainda
    não têm uma capacidade específica configurada."""
    try:
        valor = obter_capacidade_estimada_exibicao(tipo_estrutural, rua_nome)
    except Exception:
        valor = 0
    return valor if valor and valor > 0 else 20

def montar_html_nicho_id_brasil(rua_nome, coluna_num, nivel, quantidade):
    """Mesma pintura visual do montar_html_nicho, mas pra uma posição que
    vem direto do dado real da ID Brasil — não depende de a posição estar
    numa lista pré-cadastrada de colunas/níveis válidos."""
    lado = "impar" if coluna_num % 2 == 1 else "par"
    spec = obter_especificacao_casulo(rua_nome, coluna_num, lado)
    tipo_estrutural = spec.get("tipo_estrutural") or "aramado_P"
    capacidade_estimada = obter_capacidade_estimada_segura(tipo_estrutural, rua_nome)
    pct_ocupacao = (quantidade / capacidade_estimada * 100) if capacidade_estimada else 0.0

    status = "livre"
    if pct_ocupacao >= 81: status = "saturado"
    elif pct_ocupacao >= 50: status = "atencao"

    is_destaque = (
        st.session_state.busca_destaque
        and st.session_state.busca_destaque['rua'] == rua_nome
        and st.session_state.busca_destaque['nivel'] == nivel
        and st.session_state.busca_destaque['col'] == coluna_num
    )
    classe_destaque = "destaque-ativo" if is_destaque else ""

    return (
        f"<div class='nicho {status} {classe_destaque}' "
        f"title='{coluna_num:03d}-{nivel} | {quantidade}/{capacidade_estimada} peças "
        f"({pct_ocupacao:.1f}% da capacidade) | fonte: ID Brasil'>"
        f"{quantidade}/{capacidade_estimada}</div>"
    )

def renderizar_visualizador_dinamico_id_brasil(rua_nome, grade_rua):
    """Desenha a rua inteira a partir do dado real da ID Brasil: colunas e
    níveis vêm do que realmente existe (grade_rua), não de uma lista
    cadastrada à mão. Coluna ímpar cai no lado esquerdo, par no direito —
    mesma convenção visual que o app já usava."""
    colunas_presentes = sorted({col for (col, niv) in grade_rua.keys()})
    niveis_presentes = sorted({niv for (col, niv) in grade_rua.keys()})

    if not colunas_presentes:
        st.info("Nenhuma posição sincronizada da ID Brasil para esta rua ainda.")
        return

    colunas_impares = [c for c in colunas_presentes if c % 2 == 1]
    colunas_pares = [c for c in colunas_presentes if c % 2 == 0]

    st.markdown(f"<p style='text-align:center; color:#8892b0; font-size:12px;'>Fonte: dado real sincronizado da ID Brasil — {len(colunas_presentes)} colunas, {len(niveis_presentes)} níveis distintos.</p>", unsafe_allow_html=True)

    def renderizar_bloco(colunas_lado, titulo_lado, chave_col_widget):
        st.markdown("<div class='lado-container'>", unsafe_allow_html=True)
        st.markdown(f"<div class='lado-titulo'>{titulo_lado}</div>", unsafe_allow_html=True)
        if not colunas_lado:
            st.markdown("<p style='color: #8892b0; font-size: 12px; padding: 20px;'>Sem posições neste lado.</p>", unsafe_allow_html=True)
            st.markdown("</div>", unsafe_allow_html=True)
            return

        colunas_exibidas = selecionar_bloco_colunas(colunas_lado, 20, chave_col_widget)

        renderizar_cabecalho_colunas(colunas_exibidas)
        for nivel in niveis_presentes:
            grid = st.columns(len(colunas_exibidas) + 1)
            with grid[0]:
                st.markdown(f"<div style='line-height:28px; text-align:center; font-weight:bold; color:#8892b0; font-size: 10px;'>{nivel}</div>", unsafe_allow_html=True)
            for idx, col_num in enumerate(colunas_exibidas):
                with grid[idx + 1]:
                    dado = grade_rua.get((col_num, nivel))
                    if dado is None:
                        st.markdown("<div class='nicho' style='background: transparent;'>-</div>", unsafe_allow_html=True)
                    else:
                        st.markdown(montar_html_nicho_id_brasil(rua_nome, col_num, nivel, dado["quantidade"]), unsafe_allow_html=True)
        st.markdown("</div>", unsafe_allow_html=True)

    col_esq, col_dir = st.columns(2)
    with col_esq:
        renderizar_bloco(colunas_impares, "◀ Lado Ímpar", f"bloco_impar_{rua_nome}")
    with col_dir:
        renderizar_bloco(colunas_pares, "Lado Par ▶", f"bloco_par_{rua_nome}")

def montar_html_nicho(rua_selecionada, col_num, nivel, spec, chave_lado):
    if nivel not in spec["niveis"]:
        return "<div class='nicho' style='background: transparent;'>-</div>"

    chave = obter_chave_casulo(rua_selecionada, chave_lado, col_num, nivel)
    capacidade_estimada = obter_capacidade_estimada_exibicao(spec["tipo_estrutural"], rua_selecionada)

    qtd_id_brasil = st.session_state.quantidades_id_brasil.get(chave)
    if qtd_id_brasil is not None:
        # Fonte real (ID Brasil): só temos o total por casulo, sem separar
        # categoria/estação, então a % aqui é uma conta simples (total ÷
        # capacidade) — provisório até o motor de capacidade ser refeito.
        pecas_atuais = qtd_id_brasil
        pct_ocupacao = (pecas_atuais / capacidade_estimada * 100) if capacidade_estimada else 0.0
        fonte_txt = " | fonte: ID Brasil"
    else:
        dados_casulo = st.session_state.base_dados_cd.get(chave, {})
        pecas_atuais = calcular_pecas_totais(dados_casulo)
        pct_ocupacao = calcular_fracao_ocupada(dados_casulo, spec["tipo_estrutural"], rua_selecionada) * 100
        fonte_txt = " | fonte: lançamento manual"

    status = "livre"
    if pct_ocupacao >= 100: status = "saturado"
    elif pct_ocupacao >= 81: status = "saturado"
    elif pct_ocupacao >= 50: status = "atencao"

    is_destaque = (st.session_state.busca_destaque and st.session_state.busca_destaque['rua'] == rua_selecionada and st.session_state.busca_destaque['nivel'] == nivel and st.session_state.busca_destaque['col'] == col_num)
    classe_destaque = "destaque-ativo" if is_destaque else ""

    return f"<div class='nicho {status} {classe_destaque}' title='{col_num:03d}-{nivel} | {pecas_atuais}/{capacidade_estimada} peças ({pct_ocupacao:.1f}% da capacidade){fonte_txt}'>{pecas_atuais}/{capacidade_estimada}</div>"

def selecionar_bloco_colunas(todas_colunas, tamanho_bloco, chave_estado):
    """Mostra um bloco de colunas por vez com botões ◀ ▶ pra navegar sem
    precisar subir a tela e trocar num seletor lá em cima. chave_estado
    precisa ser única (ex: nome da rua + lado) pra cada grade ter sua
    própria posição de navegação."""
    if len(todas_colunas) <= tamanho_bloco:
        return todas_colunas

    total_blocos = math.ceil(len(todas_colunas) / tamanho_bloco)
    chave_idx = f"bloco_idx_{chave_estado}"
    if chave_idx not in st.session_state:
        st.session_state[chave_idx] = 0
    st.session_state[chave_idx] = max(0, min(st.session_state[chave_idx], total_blocos - 1))
    idx = st.session_state[chave_idx]

    col_nav1, col_nav2, col_nav3 = st.columns([1, 3, 1])
    with col_nav1:
        if st.button("◀", key=f"prev_{chave_idx}", disabled=(idx == 0), use_container_width=True):
            st.session_state[chave_idx] -= 1
            st.rerun()
    with col_nav2:
        inicio = todas_colunas[idx * tamanho_bloco]
        fim = todas_colunas[min((idx + 1) * tamanho_bloco, len(todas_colunas)) - 1]
        st.markdown(
            f"<p style='text-align:center; color:#8892b0; font-size:12px; padding-top:6px;'>"
            f"Bloco {idx + 1}/{total_blocos} — colunas {inicio:03d} a {fim:03d}</p>",
            unsafe_allow_html=True
        )
    with col_nav3:
        if st.button("▶", key=f"next_{chave_idx}", disabled=(idx >= total_blocos - 1), use_container_width=True):
            st.session_state[chave_idx] += 1
            st.rerun()

    return todas_colunas[idx * tamanho_bloco: (idx + 1) * tamanho_bloco]

def renderizar_cabecalho_colunas(lista_colunas):
    grid_header = st.columns(len(lista_colunas) + 1)
    with grid_header[0]:
        st.markdown("<div style='font-size:10px;'>&nbsp;</div>", unsafe_allow_html=True)
    for idx, col_num in enumerate(lista_colunas):
        with grid_header[idx + 1]:
            st.markdown(f"<div style='text-align:center; font-weight:bold; color:#ffcc00; font-size:10px;'>{col_num:03d}</div>", unsafe_allow_html=True)

# ==========================================
# PERSISTÊNCIA EM BANCO DE DADOS (POSTGRES/SUPABASE)
# ==========================================
# O app usa o Session Pooler do Supabase por PostgreSQL.
# As credenciais ficam protegidas nos Secrets do Streamlit.
#
# Formato recomendado dos Secrets atuais:
# SUPABASE_HOST = "aws-0-ca-central-1.pooler.supabase.com"
# SUPABASE_PORT = "5432"
# SUPABASE_DATABASE = "postgres"
# SUPABASE_USER = "postgres.<project-ref>"
# SUPABASE_PASSWORD = "..."
#
# Também aceitamos a configuração antiga [postgres], caso ela ainda exista,
# para não quebrar instalações antigas durante a transição.

def _obter_config_bd():
    """Retorna as credenciais do banco a partir dos Secrets do Streamlit."""
    try:
        if "SUPABASE_HOST" in st.secrets:
            return {
                "host": st.secrets["SUPABASE_HOST"],
                "port": int(st.secrets.get("SUPABASE_PORT", 5432)),
                "dbname": st.secrets.get("SUPABASE_DATABASE", "postgres"),
                "user": st.secrets["SUPABASE_USER"],
                "password": st.secrets["SUPABASE_PASSWORD"],
            }

        if "postgres" in st.secrets:
            cfg = st.secrets["postgres"]
            return {
                "host": cfg["host"],
                "port": int(cfg.get("port", 5432)),
                "dbname": cfg.get("dbname", "postgres"),
                "user": cfg["user"],
                "password": cfg["password"],
            }
    except Exception as e:
        st.session_state.ultimo_erro_bd = f"Secrets do banco inválidos/incompletos: {e}"
        return None

    st.session_state.ultimo_erro_bd = (
        "Secrets do banco não configurados. Use SUPABASE_HOST, SUPABASE_PORT, "
        "SUPABASE_DATABASE, SUPABASE_USER e SUPABASE_PASSWORD em "
        "Settings → Secrets do Streamlit."
    )
    return None

def obter_conexao_bd():
    if not PSYCOPG2_DISPONIVEL:
        st.session_state.ultimo_erro_bd = (
            "biblioteca 'psycopg2-binary' não instalada — "
            "adicione psycopg2-binary ao requirements.txt do repositório"
        )
        return None

    cfg = _obter_config_bd()
    if cfg is None:
        return None

    try:
        conn = psycopg2.connect(
            host=cfg["host"],
            port=cfg["port"],
            dbname=cfg["dbname"],
            user=cfg["user"],
            password=cfg["password"],
            sslmode="require",
            connect_timeout=10,
        )
        st.session_state.ultimo_erro_bd = None
        return conn
    except Exception as e:
        st.session_state.ultimo_erro_bd = f"falha ao conectar no Postgres/Supabase: {e}"
        return None

def testar_conexao_bd():
    """Testa a conexão e fecha o socket para não deixar conexões penduradas."""
    conn = obter_conexao_bd()
    if conn is None:
        return False
    try:
        conn.close()
        return True
    except Exception as e:
        st.session_state.ultimo_erro_bd = f"falha ao fechar conexão de teste: {e}"
        return False

# ==========================================
# INTEGRAÇÃO API ID BRASIL — SOMENTE LEITURA (GET)
# ==========================================
# Regra severa deste projeto: esta integração NUNCA envia dados para a API
# ID Brasil. Só existe uma função de rede aqui (`_chamar_api_id_brasil`) e
# ela usa exclusivamente requests.get(...). Não adicionar requests.post,
# requests.put, requests.patch ou requests.delete para essa API neste
# arquivo — se precisar escrever algo, é outro sistema, não este.
#
# Autenticação: HTTP Basic (Authorization: Basic base64(usuario:senha)).
# Credenciais ficam nos Secrets do Streamlit, nunca no código-fonte.
#
# Formato esperado nos Secrets (Settings → Secrets do Streamlit):
# ID_BRASIL_API_BASE_URL = "https://host-da-api"   # sem barra no final, sem rota
# ID_BRASIL_API_USUARIO = "..."
# ID_BRASIL_API_SENHA = "..."
#
# Também aceitamos a variação em seção [id_brasil], caso prefira organizar
# os secrets em blocos:
# [id_brasil]
# base_url = "..."
# usuario = "..."
# senha = "..."

def _obter_config_id_brasil():
    """Retorna (base_url, usuario, senha) a partir dos Secrets do Streamlit,
    ou None se não estiver configurado/incompleto."""
    try:
        if "ID_BRASIL_API_BASE_URL" in st.secrets:
            return {
                "base_url": st.secrets["ID_BRASIL_API_BASE_URL"].rstrip("/"),
                "usuario": st.secrets["ID_BRASIL_API_USUARIO"],
                "senha": st.secrets["ID_BRASIL_API_SENHA"],
            }
        if "id_brasil" in st.secrets:
            cfg = st.secrets["id_brasil"]
            return {
                "base_url": cfg["base_url"].rstrip("/"),
                "usuario": cfg["usuario"],
                "senha": cfg["senha"],
            }
    except Exception as e:
        st.session_state.ultimo_erro_id_brasil = f"Secrets da API ID Brasil inválidos/incompletos: {e}"
        return None

    st.session_state.ultimo_erro_id_brasil = (
        "Secrets da API ID Brasil não configurados. Use ID_BRASIL_API_BASE_URL, "
        "ID_BRASIL_API_USUARIO e ID_BRASIL_API_SENHA em Settings → Secrets do Streamlit."
    )
    return None

def _chamar_api_id_brasil(rota, params=None, log_visivel=True):
    """Faz UM ÚNICO tipo de chamada à API ID Brasil: um GET autenticado via
    HTTP Basic numa rota relativa à base_url (ex: 'casulo', 'casulo/total').
    Retorna o JSON decodificado (dict/list) em caso de sucesso, ou None em
    caso de falha (o erro fica em st.session_state.ultimo_erro_id_brasil).

    Não escreve nada na API — só leitura, por regra do projeto.
    """
    if not REQUESTS_DISPONIVEL:
        st.session_state.ultimo_erro_id_brasil = (
            "biblioteca 'requests' não instalada — adicione requests ao requirements.txt do repositório"
        )
        return None

    cfg = _obter_config_id_brasil()
    if cfg is None:
        return None

    url = f"{cfg['base_url']}/{rota.lstrip('/')}"
    if log_visivel:
        # Log visível na tela — assim dá pra conferir, a cada clique, que a
        # chamada é sempre um GET e pra onde ela está indo (sem expor a senha).
        st.caption(f"🔎 Chamando: **GET** `{url}` (params={params})")
    try:
        resposta = requests.get(
            url,
            auth=HTTPBasicAuth(cfg["usuario"], cfg["senha"]),
            params=params,
            timeout=20,
        )
        if log_visivel:
            st.caption(f"↩️ Método realmente enviado pelo servidor HTTP: **{resposta.request.method}** — status {resposta.status_code}")
        resposta.raise_for_status()
        st.session_state.ultimo_erro_id_brasil = None
        return resposta.json()
    except requests.exceptions.RequestException as e:
        st.session_state.ultimo_erro_id_brasil = f"falha ao consultar API ID Brasil ({rota}): {e}"
        return None
    except ValueError as e:
        # resposta não veio em JSON válido
        st.session_state.ultimo_erro_id_brasil = f"resposta da API ID Brasil ({rota}) não é JSON válido: {e}"
        return None

def consultar_casulos_id_brasil(offset=0, log_visivel=True):
    """GET /casulo?offset=... — posições de estoque, uma página por vez."""
    return _chamar_api_id_brasil("casulo", params={"offset": offset}, log_visivel=log_visivel)

def consultar_total_casulos_id_brasil():
    """GET /casulo/total — inteiro puro com a contagem total de casulos,
    usado pra saber quantas páginas percorrer em consultar_casulos_id_brasil."""
    return _chamar_api_id_brasil("casulo/total")

def salvar_snapshot_id_brasil(itens):
    """Substitui TODO o conteúdo da tabela estoque_id_brasil pelos itens
    informados: apaga o snapshot anterior e grava o novo (delete + insert),
    igual ao padrão já usado em salvar_lote_no_banco(). Os dados antigos são
    descartados — não fica histórico acumulado, só o retrato mais recente.

    itens: lista de dicts com id_externo, rua, linha, coluna, identificacao,
    status, quantidade_itens, chave_casulo (chave_casulo pode ser None
    quando a posição não bate com nenhum casulo mapeado no sistema).
    """
    conn = obter_conexao_bd()
    if conn is None:
        return None
    try:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM estoque_id_brasil")
            tamanho_bloco = 500
            for i in range(0, len(itens), tamanho_bloco):
                bloco = itens[i:i + tamanho_bloco]
                marcadores = ", ".join(["(%s, %s, %s, %s, %s, %s, %s, %s, now())"] * len(bloco))
                valores_achatados = []
                for it in bloco:
                    valores_achatados.extend([
                        it["id_externo"], it["rua"], it["linha"], it["coluna"],
                        it["identificacao"], it["status"], it["quantidade_itens"],
                        it["chave_casulo"],
                    ])
                cur.execute(
                    f"""INSERT INTO estoque_id_brasil
                        (id_externo, rua, linha, coluna, identificacao, status, quantidade_itens, chave_casulo, sincronizado_em)
                        VALUES {marcadores}""",
                    valores_achatados
                )
        conn.commit()
        conn.close()
        return True
    except Exception as e:
        try:
            conn.rollback()
            conn.close()
        except Exception:
            pass
        st.session_state.ultimo_erro_id_brasil = f"falha ao salvar snapshot no Supabase: {e}"
        return False

def carregar_snapshot_id_brasil_do_banco():
    """Carrega o snapshot mais recente salvo em estoque_id_brasil, no formato
    {chave_casulo: quantidade_itens} — só as linhas que resolveram uma chave
    válida entram no dicionário. Retorna None se o banco não estiver
    disponível (nesse caso o Visualizador cai pro lançamento manual, como
    sempre foi)."""
    conn = obter_conexao_bd()
    if conn is None:
        return None
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT chave_casulo, quantidade_itens FROM estoque_id_brasil WHERE chave_casulo IS NOT NULL")
            linhas = cur.fetchall()
        conn.close()
    except Exception as e:
        try:
            conn.close()
        except Exception:
            pass
        st.session_state.ultimo_erro_id_brasil = str(e)
        return None
    return {chave: int(qtd) for chave, qtd in linhas}

def carregar_grade_id_brasil_do_banco():
    """Carrega TODO o snapshot da ID Brasil, indexado por rua (no formato
    interno 'Rua NN') -> {(coluna_int, linha): {"quantidade":..., "status":...}}.
    Ao contrário de carregar_snapshot_id_brasil_do_banco, isso NÃO depende do
    ESTRUTURA_CD pra decidir o que existe — usa exatamente as posições que a
    ID Brasil informou, sem filtrar por faixa de coluna/nível conhecida.
    Retorna None se o banco não estiver disponível."""
    conn = obter_conexao_bd()
    if conn is None:
        return None
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT rua, linha, coluna, status, quantidade_itens FROM estoque_id_brasil")
            linhas = cur.fetchall()
        conn.close()
    except Exception as e:
        try:
            conn.close()
        except Exception:
            pass
        st.session_state.ultimo_erro_id_brasil = str(e)
        return None

    grade = {}
    for rua_txt, linha_txt, coluna_txt, status_txt, qtd in linhas:
        try:
            rua_num = int(rua_txt)
            coluna_num = int(coluna_txt)
        except (TypeError, ValueError):
            continue
        rua_nome = f"Rua {rua_num:02d}"
        nivel = str(linha_txt).upper()
        grade.setdefault(rua_nome, {})[(coluna_num, nivel)] = {
            "quantidade": int(qtd or 0),
            "status": str(status_txt or ""),
        }
    return grade

# Ruas que a ID Brasil rastreia mas que ainda NÃO são casulos mapeados no
# Visualizador (ex: porta-palete). Ficam de fora do modo dinâmico até serem
# mapeadas — decisão tomada com você em 2026, não é esquecimento.
RUAS_FORA_DO_VISUALIZADOR_ID_BRASIL = {"Rua 01"}

# Decisão sua: manter SEMPRE a estrutura cadastrada (ESTRUTURA_CD) como
# fonte do layout (colunas/níveis/lado) — a ID Brasil só entra como
# QUANTIDADE real dentro dessa estrutura (via quantidades_id_brasil em
# montar_html_nicho), nunca como fonte do próprio layout. A grade genérica
# "tudo junto" (140 colunas x 22 níveis iguais pra toda rua) fica desligada
# até você corrigir o ESTRUTURA_CD pra bater com a planta física real —
# então isso é False por enquanto, de propósito.
USAR_GRADE_DINAMICA_ID_BRASIL = False

def sincronizar_snapshot_completo_id_brasil():
    """Percorre TODAS as páginas de GET /casulo (só leitura), resolve a chave
    interna (rua|lado|coluna|nível) de cada posição usando a mesma lógica já
    usada na Consulta Rápida, e substitui o snapshot salvo em
    estoque_id_brasil no Supabase. Retorna um resumo (dict), ou None se nem
    chegou a buscar o total (ex: erro de conexão/autenticação)."""
    total = consultar_total_casulos_id_brasil()
    if not isinstance(total, int):
        return None

    todos_itens = []
    offset = 0
    while True:
        pagina = consultar_casulos_id_brasil(offset=offset, log_visivel=False)
        if not pagina:
            break
        todos_itens.extend(pagina)
        offset += len(pagina)
        if offset >= total:
            break
        if offset > total + 1000:  # trava de segurança contra loop infinito
            break

    processados = []
    nao_resolvidos = 0
    for item in todos_itens:
        try:
            rua_num = int(item["rua"])
            nivel = str(item["linha"]).upper()
            coluna = int(item["coluna"])
        except (KeyError, TypeError, ValueError):
            nao_resolvidos += 1
            continue

        chave, erro = resolver_chave_por_endereco(rua_num, nivel, coluna)
        if erro:
            chave = None
            nao_resolvidos += 1

        processados.append({
            "id_externo": item.get("id"),
            "rua": item.get("rua"),
            "linha": item.get("linha"),
            "coluna": item.get("coluna"),
            "identificacao": item.get("identificacao"),
            "status": item.get("status"),
            "quantidade_itens": int(item.get("quantidadeItens", 0) or 0),
            "chave_casulo": chave,
        })

    salvou = salvar_snapshot_id_brasil(processados)
    return {
        "total_api": total,
        "total_lido": len(todos_itens),
        "resolvidos": len(processados) - nao_resolvidos,
        "nao_resolvidos": nao_resolvidos,
        "salvou_no_banco": salvou,
    }

