def salvar_relatorio_no_banco(grupos, nome_arquivo, importado_por):
    """grupos: [(grupo, qtd), ...]. Cria um novo registro de importação e
    grava os grupos vinculados a ele — NÃO apaga importações anteriores,
    fica um histórico (a tela sempre lê a mais recente).
    Retorna: True (salvou), False (banco configurado mas falhou), None (banco não configurado)."""
    conn = obter_conexao_bd()
    if conn is None:
        return None
    try:
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO relatorios_importados (nome_arquivo, importado_por, importado_em) VALUES (%s, %s, now()) RETURNING id",
                (nome_arquivo, importado_por)
            )
            relatorio_id = cur.fetchone()[0]
            if grupos:
                tamanho_bloco = 500
                for i in range(0, len(grupos), tamanho_bloco):
                    bloco = grupos[i:i + tamanho_bloco]
                    marcadores = ", ".join(["(%s, %s, %s)"] * len(bloco))
                    valores = [v for (grupo, qtd) in bloco for v in (relatorio_id, grupo, qtd)]
                    cur.execute(
                        f"INSERT INTO relatorio_grupos (relatorio_id, grupo, quantidade) VALUES {marcadores}",
                        valores
                    )
        conn.commit()
        conn.close()
        return True
    except Exception as e:
        try:
            conn.close()
        except Exception:
            pass
        st.session_state.ultimo_erro_bd = str(e)
        return False

def carregar_ultimo_relatorio_do_banco():
    """Retorna (grupos, meta) da importação mais recente. grupos é [] se
    nunca houve importação; None se o banco não está disponível/deu erro."""
    conn = obter_conexao_bd()
    if conn is None:
        return None, None
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT id, nome_arquivo, importado_por, importado_em FROM relatorios_importados ORDER BY importado_em DESC LIMIT 1")
            linha_meta = cur.fetchone()
            if not linha_meta:
                conn.close()
                return [], None
            relatorio_id, nome_arquivo, importado_por, importado_em = linha_meta
            cur.execute("SELECT grupo, quantidade FROM relatorio_grupos WHERE relatorio_id=%s", (relatorio_id,))
            grupos = cur.fetchall()
        conn.close()
        try:
            importado_em_txt = importado_em.strftime("%d/%m/%Y %H:%M")
        except Exception:
            importado_em_txt = str(importado_em)
        meta = {"nome_arquivo": nome_arquivo, "importado_por": importado_por, "importado_em": importado_em_txt}
        return grupos, meta
    except Exception as e:
        try:
            conn.close()
        except Exception:
            pass
        st.session_state.ultimo_erro_bd = str(e)
        return None, None

def extrair_totais_por_grupo_pdf(arquivo_pdf):
    """
    Lê um PDF no formato 'Resumo de Estoque do Grupo' (agrupado por GRUPO,
    detalhado por MARCA) e retorna uma lista de (nome_grupo, quantidade) com
    o SUBTOTAL de peças de cada grupo — ignora os valores de custo/venda e
    o detalhe por marca, que não são necessários pro planejamento de casulos.
    """
    leitor = pypdf.PdfReader(arquivo_pdf)
    texto_completo = ""
    for pagina in leitor.pages:
        texto_completo += pagina.extract_text(extraction_mode="layout") + "\n"

    padrao_dinheiro = re.compile(r'^\d{1,3}(\.\d{3})*,\d{2}$')
    padrao_metadado = re.compile(r'(RESUMO DE ESTOQUE|Agrupado por|Empresas:|DESCRIÇÃO|Pag\.:|Detalhado por|Emitir P\.|^\d{2}\s*-\s*CD)', re.I)

    def achar_qtd(lista_tokens):
        for t in lista_tokens:
            if padrao_dinheiro.match(t):
                continue
            if re.match(r'^\d+(\.\d{3})*$', t):
                return int(t.replace(".", ""))
        return None

    grupos = []
    grupo_atual = None

    for linha_bruta in texto_completo.split("\n"):
        linha = linha_bruta.strip()
        if not linha:
            continue
        if padrao_metadado.search(linha):
            continue

        tokens = linha.split()
        if not tokens:
            continue
        primeiro_upper = tokens[0].upper()
        n_valores_dinheiro = sum(1 for t in tokens if padrao_dinheiro.match(t))

        if primeiro_upper == "VAZIO":
            qtd = achar_qtd(tokens[1:])
            if qtd is not None:
                grupos.append(("Vazio (sem grupo)", qtd))
            continue

        if primeiro_upper == "SUBTOTAL":
            qtd = achar_qtd(tokens[1:])
            if qtd is not None and grupo_atual:
                grupos.append((grupo_atual, qtd))
            continue

        if primeiro_upper == "TOTAL":
            continue

        if n_valores_dinheiro >= 2:
            continue  # linha de marca (dado), não é cabeçalho de grupo

        grupo_atual = linha

    return grupos

def extrair_baixas_romaneio_pdf(arquivo_pdf):
    """
    Parser PROVISÓRIO para o romaneio de separação, usado só na tela de
    Expedição (modo teste). Ainda não temos um romaneio real de exemplo, então
    isso procura, em cada linha do PDF, um endereço de casulo no mesmo padrão
    usado no Localizador Global ('NNN-L-NNN', ex: 003-B-009) seguido de uma
    quantidade (o primeiro número inteiro depois do endereço na mesma linha).
    Quando tivermos um romaneio real, este parser deve ser ajustado pro layout exato.
    """
    leitor = pypdf.PdfReader(arquivo_pdf)
    texto_completo = ""
    for pagina in leitor.pages:
        texto_completo += (pagina.extract_text(extraction_mode="layout") or "") + "\n"

    padrao_endereco = re.compile(r'\b(\d{2,3})\s*-\s*([A-Za-z])\s*-\s*(\d{2,3})\b')

    linhas_extraidas = []
    for linha_bruta in texto_completo.split("\n"):
        linha = linha_bruta.strip()
        if not linha:
            continue
        m_end = padrao_endereco.search(linha)
        if not m_end:
            continue
        resto_linha = linha[m_end.end():]
        m_qtd = re.search(r'\d+', resto_linha)
        if not m_qtd:
            continue
        num_rua_str, nivel_str, col_str = m_end.groups()
        linhas_extraidas.append({
            "endereco": f"{int(num_rua_str):03d}-{nivel_str.upper()}-{int(col_str):03d}",
            "rua_num": int(num_rua_str),
            "nivel": nivel_str.upper(),
            "coluna": int(col_str),
            "quantidade": int(m_qtd.group())
        })

    return linhas_extraidas

def resolver_chave_por_endereco(rua_num, nivel, coluna):
    """
    Resolve um endereço (número da rua + nível + coluna) pra chave de casulo,
    reaproveitando a mesma lógica de determinação de lado usada na Consulta
    Rápida de Casulos. Retorna (chave, erro) — chave vem None se erro != None.
    """
    rua_alvo = f"Rua {rua_num:02d}"
    cfg = ESTRUTURA_CD.get(rua_alvo)
    if not cfg or cfg.get("tipo") == "Inexistente":
        return None, f"{rua_alvo} não existe"

    todos_da_rua = cfg.get("cols_impar", []) + cfg.get("cols_par", []) + cfg.get("cols_seq", [])
    if todos_da_rua and coluna not in todos_da_rua:
        return None, f"coluna {coluna:03d} não existe na {rua_alvo}"

    if "cols_seq" in cfg:
        lado = "seq"
    elif rua_alvo == "Rua 11":
        lado = "par"
    elif coluna in cfg.get("cols_impar", []):
        lado = "impar"
    elif coluna in cfg.get("cols_par", []):
        lado = "par"
    else:
        return None, f"não consegui determinar o lado da coluna {coluna:03d}"

    chave = obter_chave_casulo(rua_alvo, lado, coluna, nivel)
    if chave not in st.session_state.base_dados_cd:
        return None, f"casulo {rua_alvo} {coluna:03d}-{nivel} não existe (nível inválido pra esse tipo de casulo)"

    return chave, None

